using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Settings.PaymentMethods;public class EditModel(ApplicationDbContext db,IPermissionService permissions):PageModel{[BindProperty]public PaymentMethod Item{get;set;}=null!;public async Task<IActionResult> OnGetAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.PaymentMethods,PermissionAction.Update))return Forbid();var x=await db.PaymentMethods.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();Item=x;return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.PaymentMethods,PermissionAction.Update))return Forbid();if(!ModelState.IsValid)return Page();var x=await db.PaymentMethods.SingleOrDefaultAsync(x=>x.Id==Item.Id);if(x is null)return NotFound();x.Name=Item.Name;x.Notes=Item.Notes;await db.SaveChangesAsync();TempData["Message"]="تم تعديل طريقة الدفع";return RedirectToPage("Index");}}
